#include <stdio.h>

int sumTo(int n) {
    int total = 0;

    for (int i = 1; i <= n; i++) {
        total = total + i;
    }

    return total;
}

int main(void) {
    printf("%d\n", sumTo({n1}));
    printf("%d\n", sumTo({n2}));
    return 0;
}
